<script type="application/json" data-siget-chart="sigetAgencyChart">{!! json_encode(['type'=>'bar','labels'=>$directions->pluck('unit')->values()->all(),'datasets'=>[['label'=>'Esperadas','data'=>$directions->pluck('expected')->values()->all(),'backgroundColor'=>'#152f5f','borderRadius'=>3],['label'=>'Recibidas','data'=>$directions->pluck('received')->values()->all(),'backgroundColor'=>'#147d85','borderRadius'=>3],['label'=>'Validadas','data'=>$directions->pluck('validated')->values()->all(),'backgroundColor'=>'#29925a','borderRadius'=>3]],'options'=>['indexAxis'=>'x','scales'=>['y'=>['beginAtZero'=>true],'x'=>['grid'=>['display'=>false]]]]]) !!}</script><script type="application/json" data-siget-chart="sigetTrendChart">{!! json_encode(['type'=>'line','labels'=>$trend->pluck('period')->values()->all(),'datasets'=>[['label'=>'Esperadas','data'=>$trend->pluck('expected')->values()->all(),'borderColor'=>'#152f5f','backgroundColor'=>'transparent'],['label'=>'Recibidas','data'=>$trend->pluck('received')->values()->all(),'borderColor'=>'#147d85','backgroundColor'=>'transparent'],['label'=>'Validadas','data'=>$trend->pluck('validated')->values()->all(),'borderColor'=>'#29925a','backgroundColor'=>'transparent']], 'options'=>['scales'=>['y'=>['beginAtZero'=>true],'x'=>['grid'=>['display'=>false]]]]]) !!}</script><script>(()=>{const form=document.getElementById('execFilterForm'),range=document.getElementById('execCustomRange'),from=form?.querySelector('[name=from]'),to=form?.querySelector('[name=to]'),agency=document.getElementById('exec-agency-filter'),pauta=document.getElementById('exec-pauta-filter');const month=d=>d.toISOString().slice(0,7);const syncCampaigns=()=>{if(!agency||!pauta)return;const agencyId=agency.value;Array.from(pauta.options).forEach(option=>{if(!option.value)return;option.hidden=!!agencyId&&option.dataset.agencyId&&option.dataset.agencyId!==agencyId});const selected=pauta.selectedOptions[0];if(agencyId&&selected?.dataset.agencyId&&selected.dataset.agencyId!==agencyId)pauta.value='';};agency?.addEventListener('change',syncCampaigns);document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-range]').forEach(x=>x.classList.remove('active'));b.classList.add('active');range?.classList.toggle('d-none',b.dataset.range!=='custom');if(!from||!to||b.dataset.range==='custom')return;const now=new Date(),end=new Date(now),start=new Date(now);if(b.dataset.range==='quarter')start.setMonth(Math.floor(now.getMonth()/3)*3);if(b.dataset.range==='week')start.setDate(now.getDate()-now.getDay()+1);if(b.dataset.range==='today')start.setDate(now.getDate());from.value=month(start);to.value=month(end);form.submit()}));document.getElementById('execPeriodSelect')?.addEventListener('change',e=>{range?.classList.toggle('d-none',e.target.value!=='custom');if(e.target.value==='month')document.querySelector('[data-range=month]')?.click();if(e.target.value==='quarter')document.querySelector('[data-range=quarter]')?.click()});syncCampaigns()})();</script>
